import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { CLUSTER_IDS, loadNuclearPack, nuclearBriefSections } from "../src/context-profile.js";
import { type DaemonReply, sealDaemonPayload } from "./counted-check.js";
import { type Harness, ORIGIN, VirtualAuthenticator, b64, claims, daemonHeaders, signIn, startHarness, withClaim } from "./harness.js";

/**
 * The composer against the real packs/nuclear-grade (generated by scripts/generate-nuclear-pack.mjs),
 * not the test fixture: the manifest shape the generator writes is the one loadNuclearPack reads.
 */
const repo = resolve(fileURLToPath(new URL("../../../", import.meta.url)));
const packDir = join(repo, "packs", "nuclear-grade");
const manifest = JSON.parse(readFileSync(join(packDir, "manifest.json"), "utf8")) as {
  commit: string;
  core: { card: string; skills: string[] };
  clusters: Record<string, { card: string; skills: string[] }>;
  templates: Record<string, string[]>;
};
const text = (rel: string) => readFileSync(join(packDir, rel), "utf8");

describe("the real nuclear-grade pack", () => {
  it("loads through loadNuclearPack with every cluster the rule table knows, and every skill and template the manifest names", () => {
    const pack = loadNuclearPack(packDir);
    expect(pack).not.toBeNull();
    expect(pack!.commit).toBe(manifest.commit);
    expect(Object.keys(pack!.clusters).sort()).toEqual([...CLUSTER_IDS].sort());
    expect(pack!.core.card).toBe(text(manifest.core.card));
    const skills = new Set([...manifest.core.skills, ...Object.values(manifest.clusters).flatMap((c) => c.skills)]);
    expect(Object.keys(pack!.skills).sort()).toEqual([...skills].sort());
    for (const [mode, list] of Object.entries(manifest.templates)) expect(pack!.templates[mode]!.map((t) => t.name)).toEqual(list);
    const all = nuclearBriefSections(pack!, [...CLUSTER_IDS], "author", "high-consequence");
    for (const id of CLUSTER_IDS) expect(all.sections).toContain(text(manifest.clusters[id]!.card));
  });
});

let h: Harness;
let cookie: string;
const passkey = new VirtualAuthenticator();

beforeAll(async () => {
  h = await startHarness(); // the real repository root, so packs/nuclear-grade is the real pack
  cookie = await signIn(h.app, passkey);
}, 120_000);
afterAll(async () => h?.stop());

const asOwner = (method: "GET" | "POST", url: string, payload?: unknown) =>
  h.app.inject({ method, url, headers: { cookie, ...(method === "GET" ? {} : { origin: ORIGIN }) }, ...(payload !== undefined ? { payload: payload as object } : {}) });
const asDaemon = async (url: string, payload: unknown): Promise<DaemonReply> => {
  const body = await sealDaemonPayload(h.admin, url, withClaim(url, payload as Record<string, unknown>));
  return (await h.app.inject({ method: "POST", url, headers: daemonHeaders, payload: body })) as DaemonReply;
};
interface Job {
  run: { id: string; role: string; package_id: string };
  inputs: { name: string; content_base64: string }[];
  claim: { token: string };
}
async function claim(): Promise<Job | null> {
  const r = await asDaemon("/runner/claim", { runtimes: ["fake"] });
  if (r.statusCode === 204) return null;
  const job = r.json() as Job;
  claims.set(job.run.id, job.claim.token);
  return job;
}

describe("a Nuclear brief from the real pack", () => {
  it("carries the real Core and cluster cards in BRIEF.md and the real skills and templates as inputs", async () => {
    expect((await asOwner("POST", "/captures", { lane: "internal", text: "Make REAL1" })).statusCode).toBe(201);
    const intake = await claim();
    if (!intake) throw new Error("no intake job");
    const draft = {
      schema_version: "0.1.0", id: "REAL1", revision: 0, title: "Package REAL1", project: "PRJ-TEST", mode: "general", status: "draft",
      rigor_mode: "high-consequence", data_lane: "internal", objective: "Produce REAL1",
      deliverables: [{ id: "REAL1-D1", type: "report", format: ["md"] }], design_inputs: [],
      agent_assignment: [{ role: "general-author", agent_baseline: "author", baseline_revision: 0 }],
      acceptance_criteria: ["The report exists"],
      verification: { method: "agent-pre-check", verifier: "checker", verifier_receives: ["deliverables"], required_custody: { decisive_evidence_generated_by: "verifier", preparer_may_present: false } },
    };
    const done = await asDaemon(`/runner/runs/${intake.run.id}/complete`, { status: "succeeded", outputs: [{ name: "package.json", content_base64: b64(JSON.stringify(draft)) }] });
    expect(done.statusCode, done.body).toBeLessThan(300);
    const id = ((await asOwner("GET", "/packages")).json() as { id: string }[]).find((p) => p.id.endsWith("-REAL1"))?.id;
    if (!id) throw new Error("package not drafted");
    const o = await asOwner("POST", `/packages/${id}/decisions/options`, { kind: "release", package_revision: 0 });
    expect(o.statusCode, o.body).toBe(200);
    const d = await asOwner("POST", `/packages/${id}/decisions`, { kind: "release", package_revision: 0, assertion: passkey.assert(o.json().options) });
    expect(d.statusCode, d.body).toBe(201);
    await h.admin.query("update packages set body = body || $2::jsonb where id = $1", [id, JSON.stringify({ grade: "safety" })]);

    const job = await claim();
    expect(job?.run.package_id).toBe(id);
    const input = (name: string) => job!.inputs.find((i) => i.name === name);
    const brief = Buffer.from(input("BRIEF.md")!.content_base64, "base64").toString();
    expect(brief).toContain(`Pack ${manifest.commit}.`);
    expect(brief).toContain(text(manifest.core.card));
    // general-author has write tools, high-consequence rigor, Safety grade: these three clusters.
    for (const c of ["agent-authority", "configuration-management", "review-panel"]) expect(brief).toContain(text(manifest.clusters[c]!.card));
    expect(brief).not.toContain(text(manifest.clusters["claims-discipline"]!.card));
    for (const s of manifest.core.skills) {
      const f = input(`reference/${s}/SKILL.md`);
      expect(f, s).toBeDefined();
      expect(Buffer.from(f!.content_base64, "base64").equals(readFileSync(join(packDir, "reference", s, "SKILL.md")))).toBe(true);
    }
    for (const m of ["standard", "cm"]) for (const t of manifest.templates[m]!) expect(input(`templates/${m}/${t}`), `${m}/${t}`).toBeDefined();
    expect(job!.inputs.some((i) => i.name.startsWith("templates/quick/"))).toBe(false);
    await asDaemon(`/runner/runs/${job!.run.id}/complete`, { status: "failed", error: "test over", outputs: [] });
  });
});
